    const u = payUnit(x.v), bad = [];
    const got = replay(u, pool0());
    if (got.length !== 36 || x.writes.length !== 36) bad.push(got.length + ' stores, machine ' + x.writes.length);
    for (let j = 0; j < Math.min(got.length, x.writes.length) && !bad.length; j++)
      if (got[j].join() !== x.writes[j].join()) bad.push('store ' + j + ' ' + got[j].join() + ', machine ' + x.writes[j].join());
