        const r = ef();
        if (key) Object.assign(forced[key], { r, held: g.heldWrites.length, ops: g.heldOps, pend: g.stormPending, win: g.diWindows.length });
        if (n === 3) g.ram[0xFECE] = 0xC5;            // then on to the payload: $C6, $C7 ramping, $C8 the payload
