  if (bad.length) console.log('   EK1 (state, path, machine T, engine T, T ok, writes ok): ' + JSON.stringify(bad.slice(0, 6)));
  checkTrue('*** M7.88 EK1 -- $931A CHARGES ITSELF, RUN BY RUN. ***  Every one of the fixture’s ' + EK.rows.length +
            ' kept runs (' + nat + ' natural over ' + EK.paths + ' paths, ' + forced + ' FORCED for the arms play never ' +
            'took), replayed from its own entry state, costs in the engine EXACTLY the machine’s T (' + EK.T.join('..') +
            ' natural, the walk and its ' + EK.probe_paths + '-path probe included, $8BC2 apart: ' + births + ' runs ' +
            'with a birth), and the ' + wrote + ' without a birth leave the machine’s writes and no other',
            !bad.length && EK.rows.length >= 40 && forced >= 15 && births >= 3 && EK.model['931A_bad'].length === 0 &&
            EK.model['9377_bad'].length === 0);
  /* ...and THE PASS: in play the engine charges the run's own T in place of passcost's provisional median */
  const g = new PB.BB_Game(A), kb = new S.Keyboard();
  g.gameStart();
  const okp = playFromTitle(g, '1');
  for (let f = 0; f < 400 && (g.roundSeq || !(g.ram[0xFD87] & 0x80) || !g.ram[0xFEC4]); f++) g.step(kb);
  for (let f = 0; f < 400 && !g.passes; f++) g.step(kb);
