  /* M7.89: the pass also carries $925A's own run (peLast) and its share AS CALIBRATED (cost925a 'census') */
  g.passCharge = function (r) { const ek = this.ekLast, raw = this.ekT + this.ekSub, sc = this.scLast, fa = this.fa5Last, rc = this.rcLast, pe = this.peLast, it = this.itLast; const t = orig.call(this, r); log.push([this.passLast, ek, raw, sc, fa, rc, pe, it]); return t; };
