    for (const r of CO.rows) {
      const x = safe(() => runRow(r)) || { t: NaN, wbad: 'threw', smc: new Set(), writes: 0 };
      writes += x.writes; x.smc.forEach(a => smcSeen.add(a));
      if (CO.forced.indexOf(r.state) >= 0) tags[r.state] = (tags[r.state] || 0) + 1;
      if (x.t !== r.T || x.wbad) { bad++; if (!first) first = r.state + ' slot ' + r.slot + ': ' + x.t + ' T / machine ' + r.T + (x.wbad ? ', write ' + x.wbad : '') + ' -- path ' + r.path; }
    }
