    const hold = g.extHold.bind(g), mo = g.mainOut.bind(g), rt = g.extRt.bind(g), ri = g.rvIsr.bind(g);
    g.extHold = function (a, v, t) { log.push([a, v, this.extOrg + t]); return hold(a, v, t); };
    g.mainOut = function (a, t) { if (this.extW || this.lz) outs.push([a, t]); return mo(a, t); };
    g.extRt = function (k) { rt(k); if (this.extW) hooks[k] = [this.extW.t0, this.extW.c0]; };
    /* M7.100: the giant's block is timed a frame at a time -- its writes logged as they are put (no stamp yet), and the
       frame and T it ends at when lzStep finishes it */
    const lzLog = [], lh = g.lzHold.bind(g), ls = g.lzStep.bind(g);
    let lzEnd = null, lzF = null, lzPrev = 0;
    g.lzHold = function (a, v, e) { lzLog.push([a, v, e]); return lh(a, v, e); };
    g.lzStep = function (b) { ls(b); if (!this.lz && lzEnd === null) { lzF = this.tframe + this.extBlk.paid; lzEnd = off + lzF; } };
    /* each ISR inside the block: on the block's first frame clock its point is the sum of the budgets
       so far; every write stamped before it has landed (the last value of each byte whose last write
       came after the ISR before -- an earlier ISR may draw over an earlier one, the machine's order)
       and every one after it is still held, at the moment it runs.  A lazy block's: every held write is
       still unstamped (nothing timed before the point was kept), and the last value of each byte landed
       since the ISR before is in RAM */
    let off = 0;
