    const lost = g.extLost - l0, early = g.gaEarly - e0;
    const inside = isrs.filter(i => i.edge < endT);
    const outI = Object.fromEntries(RW[Object.keys(RW)[0]].exact);
    /* a lazy block's OUT: logged once, in the frame it ends, its exact distance to the end plus its own access's wait */
