             order: isrs.length > 0 && isrs.every(i => i.landed && i.held === i.kept),
             waiting: rows.filter(r => r.n >= 1 && r.n < resumeAt).every(r => r.pend && r.passes === 0 && r.led === g.extBlk.at && r.tick === 1),
             after: rows.filter(r => r.n >= resumeAt).every(r => !r.pend && r.held === 0 && r.led === null && r.passes > 0),
