    const g = new P.BB_Game(A), r = g.ram;
    for (const [a, hx] of sd.ram) for (let i = 0; i < hx.length / 2; i++) r[a + i] = parseInt(hx.substr(2 * i, 2), 16);
    r[0xFED0] = 0; r[0xFED2] = 1;
