    const x = RV[w], m = Object.fromEntries(x.exact), u = unit(x.seed), h = u.hooks, bad = [];
    for (const k of ['repaint', 'digits', 'derive', 'panel', 'lives', 'out'])
      if (!h[k] || h[k][0] !== m[k]) bad.push(k + ' at ' + (h[k] ? h[k][0] : 'none') + ', machine ' + m[k]);
    if (u.g.extEndT !== m.ret) bad.push('end ' + u.g.extEndT + ', machine ' + m.ret);
    const rv = h.release ? h.release[0] + h.release[2] : null;          // the engine's $8C28: 'release' ends there
    if (rv !== m.reveal) bad.push('$8C28 at ' + rv + ', machine ' + m.reveal);
