    const outOk = outs.length === 1 && outs[0][0] === 0 && outs[0][1] === g.extOrg + hooks.out[1] +
                  (Object.fromEntries(RV[WORLDS[0]].exact).outI - Object.fromEntries(RV[WORLDS[0]].exact).out);
