    if (s.kind === 'reveal') for (const [a, hx] of seedOf(x, s).ram) for (let i = 0; i < hx.length / 2; i++) r[a + i] = parseInt(hx.substr(2 * i, 2), 16);
    const hooks = {}, order = [], log = [], outs = [];
