  const FN = { '8E2A': 'gameOverTimer', '8FE7': 'pauseGate', '900B': 'enemyRelease', 'A9ED': 'bossTick', '9961': 'joinCheck',
               '915F': 'hurryReset', '948F': 'extendDone', '7E80': 'elemEmit', '93DC': 'elemArm', '9E50': 'elemTick',
               'A09A': 'effectManager', 'A824': 'giantTick', '9037': 'hurryTrig', '9AEB': 'enemyFire' };
