  for (let f = 0; f < 400 && (g.roundSeq || !(g.ram[0xFD87] & 0x80) || !g.ram[0xFEC4]); f++) g.step(kb);
  for (let f = 0; f < 400 && !g.passes; f++) g.step(kb);
  const log = [], orig = g.passCharge;
  g.passCharge = function (r) { const t = orig.call(this, r); log.push(this.passLast); return t; };
  for (let f = 0; f < 4; f++) g.step(kb);
  const norm = log.filter(p => p.path === 'pass');
  const EVERY = ['7E80', '8E2A', '8FE7', '900B', '9037', '915F', '93DC', '948F', '9961', 'A9ED'];
  const kOf = a => { const w = SMF.routines[a].window; return (w.on.all[1] / w.on.all[0]) / (w.off.all[1] / w.off.all[0]); };
