      const acc = Array.from(g.pacc), at = g.pAt + (g.passSplitLook || 0), ph = ((g.passT0 - g.budget) % FD + FD) % FD, t = ps0();
      if (SPL){ SPL.acc = SPL.acc.concat(acc.map((v, i) => i & 1 ? v : v + SPL.at)); SPL.at += at; }
      else SPL = { f: curF, ph, acc, at };
