    g.budget = y.shift;
    let n = 0, seen = null, thrown = null, ph = null, nst = 0, nstAt = null, lost = false;
    g.ram = new Proxy(raw, { set(t, k, v){ t[k] = v; if (typeof k === 'string' && /^[0-9]+$/.test(k) && OBS(+k)) nst++; return true; },
                             get(t, k){ const v = t[k]; return typeof v === 'function' ? v.bind(t) : v; } });
    const take = () => { nstAt = nst; seen = y.seen.map(([a]) => raw[a]); for (const [a, v] of y.chg) raw[a] = v; };
    g.isr = function(){ n++; ph = this.gridPhV; take(); };
    if (old) g.isrSite = () => false;
    try { g.hurryReset(); } catch (e) { thrown = e.message; }
    g.ram = raw;
    const T = g.smT;
