      const at = b => { const h = seeded(x.seed); h.budget = b; let n = 0; h.isr = () => { n++; }; h.hurryReset(); return { n, lost: h.intLostAt(b) }; };
      const a0 = at(di), a1 = at(di + 1), e32 = at(ret - 32), e31 = at(ret - 31);
