    const g = new P.BB_Game(A);
    g.m128 = o.m128 !== false;
    g.skipProbe = o.skip !== undefined ? o.skip : !!sc.skip;
    if (o.skipPhase !== undefined) g.skipPhase = o.skipPhase;
