      reqs: sc.reqs.filter(r => inT(r[0], r[1])).map(sh), ereqs: sc.ereqs.filter(r => inT(r[0], r[1])).map(sh),
      waits: sc.waits.filter(r => r[1] >= lo && inT(r[6], r[7])).map(r => [r[0], r[1] + df].concat(r.slice(2, 6), [r[6] + df, r[7]])),
      isrs: sc.isrs.filter(r => r[3] !== null && inT(r[0], r[1])).map(sh), ticks: sc.ticks.filter(r => inT(r[0], r[1])).map(sh),
      p7ffd: sc.p7ffd.filter(r => inT(r[0], r[1])).map(sh), ay: sc.ay.filter(r => inT(r[0], r[1])).map(sh),
