    const cross = cur => { at(1000, FD - 10, cur); g.diWindows = [[FD - 100, FD - 10]];
      g.mwBegin(0x8E0A, 3, 0x891A, 'main', 0); g.mw.cut = true; g.mw.rem = M.STOP.REM_PT; g.mwRun(FD);
      return [g.tframe - (FD - 10), J(g.diWindows), g.intLostAt(FD), g.gridPhV, g.mwLost, !!g.mw]; };
    const b = [cross(1), cross(3)];
    /* (c) a block of 500 T: a held write at 50 and one at 150, the window [1, 118] over a call at 108 (STOP's ENTRY, REM 11) */
    const L = (wins, iff = 0) => {
      at(1000, 0, 1); g.heldWrites = []; g.extBlk = { what: 'a test block', paid: 0 };
      g.lz = { acc: [], ins: [], end: 500, x: 0, i: 0, outs: [], main: 0, last: -Infinity, wins, stops: [], hit: false };
      g.lz.stops.push({ o: 108, pc: 0x8E0A, a: 2, site: 0x94D5, iff, rem: M.STOP.REM_ENTRY });
      g.heldWrites.push([Infinity, 0xC000, 0x11, undefined, undefined, undefined, 50], [Infinity, 0xC001, 0x22, undefined, undefined, undefined, 150]);
      g.ram[0xC000] = 0; g.ram[0xC001] = 0;
      g.lz.outs.push([200, 0x05]); g.border = 0;     // an OUT past the call: made after it
    };
    L([[1, 129]]);
    g.lzStep(FD, 0);
    const c = { hit: [g.tframe, !!g.mw, g.mw && g.mw.iff, g.mw && g.mw.cut, g.mw && g.mw.rem, g.ram[0xC000], g.ram[0xC001], J(g.diWindows), g.border] };
    g.mwRun(FD);
    c.ret = [g.tframe, g.lzRes, J(g.diWindows), g.lz.x];
    g.lzStep(FD, g.tframe);
    c.end = [g.tframe, g.lz, g.ram[0xC001], g.lzRes, g.heldWrites.length, g.border, g.extSpent];
    L([[1, 129]], 1);
    try { g.lzStep(FD, 0); c.on = 'not refused'; } catch (e) { c.on = e.message; }
    L([[1, 140]]);
    try { g.lzStep(FD, 0); c.rem = 'not refused'; } catch (e) { c.rem = e.message; }
    g.lz = null; g.heldWrites = []; g.extBlk = null;
    /* (d) the heart with no pass program: the callee's entry + HEART */
    at(1000, 1000, 1); g.pacc = null; g.itHandlerO = NaN; g.passCallT = 0; g.passWrap = false; g.itSub = 0; g.mwLate = 0;
    const T = g.heartReq(4);
